import { test, expect } from '@playwright/test';

test.describe('Modal Focus Trapping', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should trap focus inside an open modal', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog', { name: /modal dialog/i });
    await expect(modal).toBeVisible();

    // Verify focus is on the modal's first interactive element
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeFocused();

    // Verify background content is not focused
    const backgroundContent = page.getByText('Page Content');
    await expect(backgroundContent).not.toBeFocused();

    // Verify focus remains inside modal when tabbing
    await closeButton.press('Tab');
    const modalInput = page.getByLabel(/modal input/i);
    await expect(modalInput).toBeFocused();

    // Verify focus remains inside modal when pressing Shift+Tab
    await modalInput.press('Shift+Tab');
    await expect(closeButton).toBeFocused();

    // Verify focus remains inside modal when pressing Escape
    await page.keyboard.press('Escape');
    await expect(modal).not.toBeVisible();
  });

  test('should restore focus to trigger element when modal is closed', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog', { name: /modal dialog/i });
    await expect(modal).toBeVisible();

    // Verify focus is on the modal's first interactive element
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeFocused();

    // Close the modal using the close button
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify focus is restored to the open button
    await expect(openButton).toBeFocused();

    // Verify background content is accessible again
    const backgroundContent = page.getByText('Page Content');
    await expect(backgroundContent).toBeVisible();
  });
});
